CREATE TABLE IF NOT EXISTS medicine_dogcat (
    item_seq VARCHAR(20) PRIMARY KEY,
    product_name VARCHAR(200),
    product_name_en VARCHAR(200),
    ingredients TEXT,
    efficacy TEXT,
    dosage TEXT,
    precaution TEXT,
    target_animal VARCHAR(200)
);


INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202311921', '펫퍼스 샴푸(흰개용)', NULL, NULL, '애견의  모발 보호 및 세정 작용', '먼저 애견의 몸에 물을 적신후 적당량을 취하여 바르
고 부드럽게 문지르고 거품을 낸 후 씻어낸다.', '1) 부작용 : 사용상 다음과 같은 이상이 있을 경우에
는 사용을 중지할 것이며 계속 사용하면
증상을 악화시키므로 전문 수의사 등에게
상담할 것.
- 사용중  붉은 반점, 부어오름, 가려움증, 자극이
있을 경우
- 적용부위가 직사광선에 의해 위와 같은 이상이
있는 경우
2) 금기사항
- 상처가 있는 곳 또는 습진 및 피부염 등의 이상이
있는 부위에는 사용을 금할 것.
3) 사용방법상의 주의사항
- 눈에 들어갔을 때에는 즉시 씻을 것.
- 사용 후 충분히 물로 씻어 내지 않으면 탈모 또는
탈색의 원인이 될 수도 있으므로 사용후 충분히
물로 씻어낼 것.
4) 기타 주의사항
- 사용후 마개를 닫아둘 것
- 유.소아의 손에 닿지 않는 곳에 보관할 것.
- 고온 내지 저온의 장소 및 일광이 닿는 곳에는
보관하지 말 것.', '애견의  모발 보호 및 세정 작용 먼저 애견의 몸에 물을 적신후 적당량을 취하여 바르
고 ');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202301140', '노바솔 주사액', 'Nobasol Injectable Solution', '레티놀팔미테이트 50,000IU, 콜레칼시페롤 25,000IU, 토코페롤아세테이트 20MG, 파라옥시안식향산메칠 0.7MG, 파라옥시안식향산프로필 0.3MG, 글리세린 150MG, 폴리옥실35·피마자유 180MG', '가축의 비타민 결핍증 치료, 임신 동물의 영양보급, 수태율 개선, 번식장애예방, 대사 장애 예방', '다음의 양을 근육내 주사
- 망아지 : 5-10ml
- 말 : 10-20ml
- 자돈 : 2-4ml
- 성돈 : 5ml
- 개, 고양이 : 1-3ml', '가. 휴약기간 : 없음
나. 사용상의 주의사항
- 수의사의 지시에 따라 사용하십시오.
- 정하여진 용법․용량을 준수하십시오.
- 안전성 및 유효성에 변화를 초래할 수 있으므로 정하여진 저장방법을 준수하십시오.
- 유효기간이 경과한 제품은 사용하지 마시고 안전하게 폐기 처리하십시오.
- 직사광선을 피하여 보관하십시오.
- 어린이의 손이 닿지 않는 곳에 보관하십시오.
- 본 약제에 과민반응을 보인 동물에는 사용하지 마십시오.', '가축의 비타민 결핍증 치료, 임신 동물의 영양보급, 수태율 개선, 번식장애예방, 대사 장애');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202311392', '닥터 블랭크 올인원 애견 샴푸', 'Dr. Blank Pet Shampoo', NULL, '애견의 모발보호 및 세정작용', '먼저 물을 온몸에 적신 후 적당량을 취해 바르고 부드럽게 문지른 후 씻어준다.', '8. 사용상의 주의사항
가. 사용상 다음과 같은 이상이 있을 경우 수의사와 상담할 것. 사용 중 붉은 반점, 부어오름, 가려움증, 자극이 있을 경우. 나. 상처가 있는 곳 또는 습진 및 피부염 등의 이상이 있는 부위에는 사용을 금할 것. 다. 사용방법상의 주의 사항. (1)눈에 들어갔을 때에는 즉시 씻을 것. (2)사용 후 충분히 물로 씻어 내지 않으면 탈모 또는 탈색의 원인이 될 수도 있으므로 사용 후 충분히 물로 씻어 낼 것. 라. 기타 주의사항. (1)사용 후 마개를 닫아 둘 것. (2)유아, 소아의 손에 닿지 않는 곳에 보관 할 것. (3)고온 내지 저온의 장소 및 일광이 닿는 곳에는 보관하지 말 것.', '애견의 모발보호 및 세정작용 먼저 물을 온몸에 적신 후 적당량을 취해 바르고 부드럽게 문지');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202311350', '닥터코넬리 프리미엄 펫 바디미스트', 'Dr Cornelly Premium Pet Body Mist', NULL, '반려동물의 악취 제거', '반려동물에게서 20cm이상 떨어진 곳에서 분사한다
반려동물의 몸에 악취가 나는 곳에 분사한 후 닦아내 주십시오.', '가. 사용상 다음과 같은 이상이 있을 경우 수의사와 상담할 것. 사용 중 붉은 반점, 부어오름, 가려움증, 자극이 있을 경우. 나. 상처가 있는 곳 또는 습진 및 피부염 등의 이상이 있는 부위에는 사용을 금할 것. 다. 사용방법상의 주의 사항. (1)눈에 들어갔을 때에는 즉시 씻을 것. 라. 기타 주의사항. (1)사용 후 마개를 닫아 둘 것. (2)유아, 소아의 손에 닿지 않는 곳에 보관 할 것. (3)고온 내지 저온의 장소 및 일광이 닿는 곳에는 보관하지 말 것. (4)제품 내 알레르기 유발 물질이 포함되어 있으므로, 사용 후 이상 증상 발생할 경우 수의사와 상담할 것', '반려동물의 악취 제거 반려동물에게서 20cm이상 떨어진 곳에서 분사한다
반려동물의 몸에 악');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202310572', '바쏘드 츄정', 'BASOD', 'Bacillus amyloliquefaciens(식품공전) 20,000,000.000CFU, Magnesium stearate(KVP) 8.000MG, Silicon dioxide(KVP) 10.000MG, Carboxymethylcellulose calcium(KVP) 16.000MG, Saccharin sodium(KVP) 1.000MG, Glucose(KVP) 58.000MG, 가금부산물 건조분(사료공정서) 7.000MG, Microcrystalline cellulose(KVP) 적량-', '가. 대상동물 : 개, 고양이
나. 정장작용, 면역증진작용, 장기능 개선', '가. 개
- 체중 10kg 까지 : 1일 1정 경구 투여
- 체중 10kg 이상 : 1일 2정(오전 1정, 오후 1정) 경구 투여
나. 고양이 : 1일 1정 경구 투여', '가. 수의사의 지시에 따라 사용하십시오.
나. 사용 전에 사용설명(서)을 충분히 읽어본 후 사용하십시오.
다. 생후 3개월 미만 동물에는 투여하지 마십시오.
라. 투여 중 설사나 구토 등 부작용을 보이는 동물에는 투여를 중단하십시오.
마. 안정성 및 유효성에 변화를 초래할 수 있으므로 저장방법을 준수하십시오.
바. 유효기간이 경과된 제품은 사용하지 마시고 안전하게 폐기하십시오.
사. 어린이나 동물의 접근이 불가능한 곳에 보관하십시오.', '개, 고양이');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202310149', '부들부들 구중청량제', NULL, NULL, '애견의 구강 냄새 제거', '애견의 구강에 뿌려준다.', '1) 구토하거나 구강내 과민반응이 나타날 경우
사용을 중지하고 수의사와 상담할 것
2) 구강, 치아에 질환이 있거나, 위장장애, 당뇨, 혈압 등의
질병이 있는 애완동물은 수의사와 상담 후 사용할 것.
3) 생후 4개월 이하, 노령, 임신 중이 애완동물의 경우
수의사와 상담 후 사용할 것.
4) 사용 후 마개를 닫아둘 것.
5) 애완동물이나 유,소아의 손에 닿지 않는 곳에 보관할 것.
6) 고온 내지 저온의 장소 및 일광이 닿는 곳에는 보관하지 말 것.
7) 동물용이므로 사람에게는 사용하지 말 것.', '애견의 구강 냄새 제거 애견의 구강에 뿌려준다.');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202312747', '오라맥스 비타-T', 'Oramax Vita-T', NULL, '반려동물의 치아 및 구강의 세정, 구취제거', '식후, 취침 후 등 구취가 있을 때 입술을 살짝 들고 본제 적당량(좌우 각 1~2방울 정도)을 떨어뜨린 후 입술 밖에서 문질러 줍니다. 또는 적당량을 구강에 묻혀 칫솔로 부드럽게 문질러 줍니다.', '1. 상처가 있는 곳, 염증이 있는 조직 부위에는 사용하지 마십시오.
2. 구강, 치아에 질병이 있을 시 수의사와 상담 후 사용하십시오.
3. 사용 후 구강 점막에 발적, 부종, 염증 등 과민반응이 나타날 시에는 투여를 중지하고 수의사와 상담하십시오.
4. 저장상의 주의사항
- 사용 후 마개를 꼭 닫아두십시오.
- 유, 소아 및 동물이 닿지 않는 곳에 보관하십시오.
- 고온 내지 저온의 장소 및 직사광선이 닿는 곳에는 보관하지 마십시오.
5. 사용상의 주의 사항
- 눈에 들어가지 않도록 주의하십시오.
- 한꺼번에 많이 섭취하면 구역질이 나타날 수 있습니다.
- 반려동물용이므로 사람에게는 사용하지 마십시오.', '반려동물의 치아 및 구강의 세정, 구취제거 식후, 취침 후 등 구취가 있을 때 입술을 살짝');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202309655', '베트케어샴푸', NULL, NULL, '애견의 세정 작용 및 세정시 모발 보호작용', '애견의 모발이나 세정을 원하는 부위를 미온수로 적신
다음 적당량을 덜어 원하는 부위에 골고루 거품을 내
여 씻은 후 깨끗한 물로 충분히 헹구어준다', '1) 사용상의 주의사항
-  장기간 같은 증상이 있을 경우에는 사용을 중지하
고 수의사와 상담할 것.
; 붉은 반점, 부어오름, 가려움증, 자극등의 이상
이 있을 경우
- 상처, 습진, 피부염 등의 이상이 있을시는 사용을
중지할 것.
- 눈에 들어 갔을 경우 즉시 씻을 것.
2) 보관 및 취급상의 주의사항
- 사용 후에는 반드시 마개를 닫아 둘 것.
- 어린이의 손에 닿지 않는 곳에 보관할 것.
- 건 냉암소에 보관할 것.', '애견의 세정 작용 및 세정시 모발 보호작용 애견의 모발이나 세정을 원하는 부위를 미온수로 ');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202311635', '미라클 순 실버 안구세정제', 'Miracle Soon Silver Eye Cleaner', NULL, '애완동물의 눈 주위에 말라 붙은 점액 분비물을 제거
하는데 사용하며, 눈에 들어간 이물질을 제거한다.', '눈의 가장자리에 모인 물질이 있으면 닦아내고 본제
를 적당히 눈에 투여하여 마사지한 다음 거즈로 닦아
낸다. 흘러내리는 여분의 액체는 깨끗하고 마른 헝겊
으로 닦아낸다. 필요한 만큼 반복 한다', '1. 수의사의 지시에 따라 사용할 것.
2. 사용법상의 주의사항:
-오염을 피하고 본제가 변색되거나 혼탁할 경우 사
용하지 말 것.
-안구 질환 치료 시 에는 수의사의 지시에 따를
것.
3. 본제 사용 후 애완동물이 눈이 지나치게 붉은 경
우, 수의사와 상담할 것.
4. 기타 주의사항:
-내복약으로 사용하지 말 것.
-어린이의 손이 닿지 않게 보관할 것.
-사용 후에는 반드시 마개를 닫아둘 것.
-고온 내지 저온의 장소 및 일광이 닿는 곳에는 보
관하지 말 것.
-애완동물용으로만 사용할 것.', '애완동물의 눈 주위에 말라 붙은 점액 분비물을 제거
하는데 사용하며, 눈에 들어간 이물질을');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202309950', '더그린 쥐눈이콩 허브 펫샴푸', NULL, NULL, '애견의 모발보호 및 세정작용', '먼저 미온수로 애견의 온몸을 적신후에 적당량의
샴푸를 덜어 바르고 부드럽게 문지른 후에 거품이 완
전히 없어질 때까지 깨끗하게 헹구어 주세요.', '1. 사용후에는 반드시 마개를 닫아 둘것.
2. 눈에 들어갔을때에는 즉시 씻어낼것.
3. 유·소아의 손이 닿지 않는 곳에 보관할것.
4. 고온내지 저온의 장소 및 직사광선이 닿는 곳에는
보관하지말것.
5. 사용후 충분히 씻어내지 않으면 탈모 또는 탈색의
원인이 될수 있으므로 물로 충분히 씻어낼것.', '애견의 모발보호 및 세정작용 먼저 미온수로 애견의 온몸을 적신후에 적당량의
샴푸를 덜어 바');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202304999', '밸런스라이트', 'BALANCELYTE', '염화나트륨(Sodium Chloride, KVP) 100,000.000MG, 염화칼륨(Potassium Chloride, KVP) 33,000.000MG, 염화마그네슘(Magnesium Chloride, KVP) 4,800.000MG, 염화칼슘수화물(Calcium Chloride Hydrate, KVP) 12,700.000MG, 시트르산(Anhydrous Citric Acid, KVP) 10,000.000MG, 포도당(Glucose, KVP) 400,000.000MG, 정제수(Purified water, KP) 적량-', '대상동물 : 닭 등 가금류 및 소, 돼지, 개
- 병후 회복기, 설사, 고온 스트레스 등으로 인한 탈수증상에 체액 전해질과 포도당 공급', '1) 1-7일간 음수 1ℓ당 1-2ml을 혼합하여 투여한다.
2) 심한 탈수시에는 수의사의 지시에 따른다.', '1) 본 제품은 동물용으로만 사용하시오.
2) 어린이 손에 닿지 않는곳에 보관하시오.
3) 희석한 액제는 전부 사용하고, 남았을 경우 재사
용 하지 마시오.
4) 다른 약제와 함께 희석하여 사용하지 마시오.', '닭 등 가금류 및 소, 돼지, 개');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202308719', '어퓨 마이 펫 올인원 샴푸', NULL, NULL, '애견 피모의 세정 작용 및 보호 작용', '애견의 모발을 미온수로 적신 다음 적당량을 덜어
원하는 부위에 골고루 거품을 내어 씻은 후
깨끗한 물로 충분히 헹구어 줍니다.', '1. 일반적 주의 사항
1) 제품사용시 붉은 반점, 부어오름, 가려움증 등의
이상증상이나 부작용 우려 등이 있는 경우 수의사등과 상담 하십시오
2) 상처가 있는 곳 또는 습진 및 피부염 등의 이상이 있는 부위에는
사용을 금지합니다.
2. 사용방법상의 주의사항
1) 눈에 들어갔을 즉시 씻어내십시오
2) 사용 후 충분히 물로 씻어 내지 않으면 탈모 및 탈색의
원인이 될 수 있으므로 충분히 물로 헹구어 주십시오
3. 보관상의 주의사항
1) 사용 후에는 반드시 마개를 닫아두십시오
2) 유아 및 소아의 손에 닿지 않는 곳에 보관 하십시오
3) 고온의 장소 및 일광이 닿는 곳에 보관 하지 마십시오
4) 사용기한 경과 시, 안전하게 폐기 처리 하십시오', '애견 피모의 세정 작용 및 보호 작용 애견의 모발을 미온수로 적신 다음 적당량을 덜어
원하');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202305164', '호호바&아르간 샴푸', 'Hohoba&Argan Shampoo', NULL, '애완동물 전용샴푸로서 피모의 세정을 위하여 사용합니다.', '1) 애견이나 고양이 몸을 미온수로 충분히 적셔준다
2) 제품을 잘 흔들어 섞은 다음 거품을 낼 수 있는 양의 샴푸를 덜어 피모에 발라 5~10분간 마사지 해준다.
3) 마사지가 끝나면 피모를 깨끗한 물로 잘 헹구어 준 다음 물기를 제거하여 건조시킨다.
4) 주 1~2회 사용이 적절하며 상태가 심한 경우에는 반복하여 사용한다.', '가. 일반적 주의사항
1) 본제는 동물전용이므로 사람에게는 사용하지 마십시오.
2) 외용제로만 사용하고 눈과 점막에 접촉되지 않도록 주의하십시오.
3) 피부가 자극되거나 발적이 지속될 경우에는 수의사와 상담하십시오.
나. 저장상의 주의사항
1) 사용후 마개를 꼭 닫아 놓으십시오.
2) 어린이 및 반려동물이 닿지 않는 곳에 보관하십시오.
3) 직사광선을 피해 건조하고 서늘한 곳에 보관하십시오.', '애완동물 전용샴푸로서 피모의 세정을 위하여 사용합니다. 1) 애견이나 고양이 몸을 미온수로');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202310574', '알엑스에이치 캡슐', 'RX-H', '티아민염산염(Thiamin hydrochloride)(KVP) 0.500MG, 리보플라빈(Riboflavin)(KVP) 0.500MG, 피리독신염산염(Pyridoxine hydrochloride)(KVP) 0.500MG, 카르니틴(L-Carnitine)(KFAC) 62.500MG, Silicon dioxide(KVP) 적량-, Magnesium stearate(KVP) 적량-, 사카린나트륨수화물 Sacharin Sodium Hydrate(KVP) 적량-, Microcrystalline cellulose(KVP) 적량-', '가. 대상동물 : 개, 고양이
나. 비타민 B군 보급, 면역기능 촉진, 활력증진, 스트레스 해소, 대사촉진, 식욕회복 및 식욕촉진', '마리당 1일 아래 용량을 경구 투여함
체중    :   1일 투여량
2.5kg미만 : 1 캡슐
2.5∼5kg : 2 캡슐
5∼7.5kg : 3 캡슐
7.5∼10kg : 4 캡슐
10∼12.5kg : 5 캡슐', '1)사용방법을 충분히 읽어본 후 사용하십시오.
2)본제를 투여하면서 동시에 동일성분의 약품을 중복 투여하지 마십시오.
3)정하여진 저장방법을 준수하십시오.
4)다른 용기에 소분하여 사용하지 마십시오.
5)어린이의 손이 닿지 않는 곳에 보관하십시오.', '개, 고양이');

INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202302314', '암비콤 주(수출용)', 'Amvicom Injection(export only)', 'L-아르기닌염산염 1.44MG, 글리신 3.2MG, L-히스티딘 1.32MG, L-이소류신 3.6MG, L-류신 4.28MG, L-리신염산염 5.44MG, L-메티오닌 3.2MG, L-페닐알라닌 5MG, L-트레오닌 3.2MG, L-트립토판 0.86MG, L-발린 3.6MG, THIAMINE HCL 4MG, 소듐리보플라빈포스페이트 0.17MG, 피리독신염산염 0.34MG, 니코틴산아미드 8MG, 칼슘클로라이드 0.08(ca으로써)MG, 포타슘클로라이드 0.21(K으로써)MG, 황산마그네슘수화물 0.08(Mg으로써)MG', '테이블 정보 :::
