INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202300707', '겐타마이신-100주', 'GENTAMICIN-100 INJECTION', 'Gentamycin sulfate 100.000MG, 주사용 증류수 적량-', '세균성 장염 및 설사, 방광염, 유방염, 신장염, 피부
염, 수송열, 부루셀라증, 패혈증, 폐렴등의 치료', '1) 일반 가축 :
