INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202308930', '울지마마이펫 개그린', 'Don''t Cry My Pet Gaegrin', NULL, '애완동물의 구강청량 및 치아보호, 구취제거', '애완동물의 입안 및 치아의 앞뒤에 골고루 발라줍니다.', '가. 구토, 발진, 두드러기, 구강 점막등에 과민반응이 나타날 경우
투여를 중지하고 수의사와 상담해 주세요.
