INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202305163', '화이트 머스크 컨디셔닝 샴푸', NULL, NULL, '반려견의 모발보호, 윤기부여 및 보습작용', '미온수로 반려견의 온몸을 샴푸로 세정 후, 본제를 적당량 덜어 온몸에 골고루 바른 후 미온수로 거품이 없어질 때 까지 충분히 헹구어 주십시오.', '가. 일반적 주의사항
