INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202311510', '프루너스 한방 허브 샴푸', 'PRUNUS HANBANG HERB SHAMPOO', NULL, '애견의 모발보호 및 세정작용', '먼저 물을 온몸에 적신 후 적당량을 취해 바르고 부드럽게 문지른 후 씻어준다.', '1) 부작용
