INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202307760', '겐타세라피 100주(수출용)', 'GENTA THERAPY 100 INJ.(export only)', '겐타마이신황산염 100MG', '1)소: 유방염, 자궁내막염, 방광염, 신장염, 폐렴, 피부염, 수송열, 브루셀라병, 출혈성 폐혈증, 전염성비기관염, 세균성 설사, 기종저 등의 예방 치료
