INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202308916', '브리더랩 실크테라피 고양이 샴푸', 'BREEDERLAB SILKTHERAPHY CAT SHAMPOO', NULL, '고양이의 피모세정을 위한 삼푸로써 털의 엉킴을 방지하고 피모를 부드럽고
윤기있게 가꾸어준다.', '가. 적당한 온수로 고양이의 피부를 충분히 적셔 주십시오
