INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202301109', '캐니가드 정', 'Caniguard tablet', 'Ivermectin 0.068MG, Pyrantel pamoate 57.000MG, 부형제 적량-', '개 심장사상충의 예방, 개구충, 개회충의 구충', '개 체중 kg당 ivermectin 6.0mcg 및 pyrantel 5mg의
