INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202309954', '잠보아 풋 케어 밤', 'Zamboa Foot Care Balm', NULL, '반려동물의 피부 및 발바닥 등에 보습을 부여하여 피부건조 및 발바닥 갈라짐을 완화한다.', '1. 반려동물과의 산책 전,후 그리고 발바닥 갈라짐, 건조증상이 있는 부위에 적당량을 발바닥에 펴바른다.
