INSERT INTO medicine_dogcat (item_seq, product_name, product_name_en, ingredients, efficacy, dosage, precaution, target_animal)
VALUES ('202309293', '포켄스 오트밀샴푸', 'Oatmeal Shampoo', NULL, '애완동물의 민감하고 연약한 피부의 보호와 세정을 위한 샴푸로써 건조한 피부에 수분을 공급하고 각질을 완화시킨다.', '1) 샴푸 전에 엉킨 털을 풀어 주세요.
